type Task = {
  id: string;
  duration: number;
  dependsOn: string[];
};

type Plan = {
  order: string[];
  layers: string[][];
  earliest: Record<string, { start: number; finish: number }>;
  totalDuration: number;
  criticalPath: string[];
};

class InputError extends Error {}
class CycleError extends Error {
  constructor(public readonly cycle: string[]) {
    super(`dependency cycle: ${cycle.join(" -> ")}`);
  }
}

function fail(message: string): never {
  throw new InputError(message);
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function parseTasks(value: unknown): Task[] {
  if (!isRecord(value) || !Array.isArray(value.tasks)) {
    fail('input must be an object with a "tasks" array');
  }

  const rawTasks = value.tasks;
  const ids = new Set<string>();
  const tasks: Task[] = [];

  rawTasks.forEach((rawTask, index) => {
    if (!isRecord(rawTask)) fail(`tasks[${index}] must be an object`);
    const id = rawTask.id;
    if (typeof id !== "string" || id.length === 0) {
      fail(`tasks[${index}].id must be a non-empty string`);
    }
    if (ids.has(id)) fail(`duplicate task id: ${JSON.stringify(id)}`);
    ids.add(id);

    const duration = rawTask.duration;
    if (typeof duration !== "number" || !Number.isFinite(duration) || duration < 0) {
      fail(`tasks[${index}].duration must be a finite non-negative number`);
    }

    const dependencies = rawTask.dependsOn === undefined ? [] : rawTask.dependsOn;
    if (!Array.isArray(dependencies)) fail(`tasks[${index}].dependsOn must be an array`);
    const seen = new Set<string>();
    for (const dependency of dependencies) {
      if (typeof dependency !== "string") {
        fail(`tasks[${index}].dependsOn must contain only strings`);
      }
      if (seen.has(dependency)) fail(`task ${JSON.stringify(id)} has duplicate dependency ${JSON.stringify(dependency)}`);
      if (dependency === id) fail(`task ${JSON.stringify(id)} cannot depend on itself`);
      seen.add(dependency);
    }
    tasks.push({ id, duration, dependsOn: [...dependencies] });
  });

  for (const task of tasks) {
    for (const dependency of task.dependsOn) {
      if (!ids.has(dependency)) {
        fail(`task ${JSON.stringify(task.id)} depends on unknown task ${JSON.stringify(dependency)}`);
      }
    }
  }
  return tasks;
}

function findCycle(tasks: Task[], byId: Map<string, Task>): string[] | undefined {
  const state = new Map<string, 0 | 1 | 2>();
  const stack: string[] = [];
  const visit = (id: string): string[] | undefined => {
    state.set(id, 1);
    stack.push(id);
    const dependencies = [...(byId.get(id)?.dependsOn ?? [])].sort();
    for (const dependency of dependencies) {
      const dependencyState = state.get(dependency) ?? 0;
      if (dependencyState === 0) {
        const cycle = visit(dependency);
        if (cycle) return cycle;
      } else if (dependencyState === 1) {
        const start = stack.indexOf(dependency);
        return [...stack.slice(start), dependency];
      }
    }
    stack.pop();
    state.set(id, 2);
    return undefined;
  };

  for (const task of [...tasks].sort((a, b) => a.id.localeCompare(b.id))) {
    if ((state.get(task.id) ?? 0) === 0) {
      const cycle = visit(task.id);
      if (cycle) return cycle;
    }
  }
  return undefined;
}

function planTasks(tasks: Task[]): Plan {
  const byId = new Map(tasks.map((task) => [task.id, task]));
  const cycle = findCycle(tasks, byId);
  if (cycle) throw new CycleError(cycle);

  const dependents = new Map<string, string[]>();
  const remaining = new Map<string, number>();
  for (const task of tasks) {
    remaining.set(task.id, task.dependsOn.length);
    for (const dependency of task.dependsOn) {
      const list = dependents.get(dependency) ?? [];
      list.push(task.id);
      dependents.set(dependency, list);
    }
  }
  const ready = tasks.filter((task) => task.dependsOn.length === 0).map((task) => task.id).sort();
  const order: string[] = [];
  while (ready.length) {
    const id = ready.shift()!;
    order.push(id);
    for (const dependent of (dependents.get(id) ?? []).sort()) {
      const count = remaining.get(dependent)! - 1;
      remaining.set(dependent, count);
      if (count === 0) {
        ready.push(dependent);
        ready.sort();
      }
    }
  }

  const earliest: Record<string, { start: number; finish: number }> = {};
  const layerById = new Map<string, number>();
  const bestPath = new Map<string, string[]>();
  for (const id of order) {
    const task = byId.get(id)!;
    let start = 0;
    let layer = 0;
    let path: string[] = [id];
    for (const dependency of task.dependsOn) {
      const dependencyTime = earliest[dependency];
      start = Math.max(start, dependencyTime.finish);
      layer = Math.max(layer, layerById.get(dependency)! + 1);
      const candidate = [...bestPath.get(dependency)!, id];
      if (candidate.reduce((sum, node) => sum + byId.get(node)!.duration, 0) >
          path.reduce((sum, node) => sum + byId.get(node)!.duration, 0) ||
          (candidate.reduce((sum, node) => sum + byId.get(node)!.duration, 0) ===
            path.reduce((sum, node) => sum + byId.get(node)!.duration, 0) && candidate.join("\0") < path.join("\0"))) {
        path = candidate;
      }
    }
    earliest[id] = { start, finish: start + task.duration };
    layerById.set(id, layer);
    bestPath.set(id, path);
  }

  const layerCount = order.length ? Math.max(...order.map((id) => layerById.get(id)!)) + 1 : 0;
  const layers = Array.from({ length: layerCount }, () => [] as string[]);
  for (const id of order) layers[layerById.get(id)!].push(id);
  layers.forEach((layer) => layer.sort());

  const totalDuration = tasks.length ? Math.max(...tasks.map((task) => earliest[task.id].finish)) : 0;
  let criticalPath: string[] = [];
  for (const id of tasks.map((task) => task.id).sort()) {
    if (earliest[id].finish === totalDuration) {
      const candidate = bestPath.get(id)!;
      if (!criticalPath.length || candidate.join("\0") < criticalPath.join("\0")) criticalPath = candidate;
    }
  }
  return { order, layers, earliest, totalDuration, criticalPath };
}

async function main(args: string[]): Promise<void> {
  if (args.length !== 2 || args[0] !== "plan" || args[1].startsWith("-")) {
    fail("usage: bun run src/cli.ts plan INPUT.json");
  }
  let input: unknown;
  try {
    input = JSON.parse(await Bun.file(args[1]).text());
  } catch (error) {
    fail(`cannot read or parse input JSON: ${error instanceof Error ? error.message : String(error)}`);
  }
  console.log(JSON.stringify(planTasks(parseTasks(input))));
}

